INSERT INTO recipes(id,name,search_text,servings,portion_type,minutes,water_ml,steps,allergens,nutrition,provenance,seed_version,created_at) VALUES('home-011','红烧牛肉','红烧牛肉 瘦牛肉 胡萝卜 土豆 生姜 大豆油 淡色酱油',1,'dish',70,300,'["牛肉切小块，胡萝卜和土豆去皮切块，生姜切片。","牛肉入冷水锅焯煮后捞出，锅中放大豆油和姜片，加入牛肉翻炒。","加入淡色酱油和300毫升水，烧开后小火炖约40分钟，水少时补充开水。","加入胡萝卜和土豆，继续炖约20分钟，确认牛肉熟透、蔬菜软熟后出锅。"]','["大豆","小麦"]','{"kcal":219.38,"protein":17.39,"fat":6.01,"carbs":25.93,"fiber":null,"sodiumMg":null,"sugar":null,"saturatedFat":null}','{"printedPage":26,"pdfPage":28,"excerpt":"红烧牛肉（牛瘦肉 60g，胡萝卜 100g，土豆 100g，生姜*2g）","changes":"保留原文主料用量；补充单菜调料克数、水量和制作步骤；食材按现有TFDA样品匹配。","matchNotes":"青菜选小白菜，牛瘦肉选修清前胸肉，鲈鱼选日本花鲈去皮可食肉，香干选五香豆干，盐选岩盐；使用对应样品估算。","sourceTitle":"成人肥胖食养指南（2024年版）","publisher":"国家卫生健康委办公厅","sourceUrl":"https://wjw.baoji.gov.cn/col2223/col2269/202403/P020241228641521653546.pdf","sourceSha256":"ce7e43937883f2d89bb3b505a410d023df510027e2015457d2800e98f5a330a2","nutritionSource":"TFDA","nutritionRelease":"snapshot-2026-10-20","calculation":"sum(raw_edible_or_as_sold_grams * TFDA_per100g / 100); no cooking retention or yield factor","stepsOrigin":"editorial","waterOrigin":"editorial"}','home-2024-v1','2026-10-20');
