INSERT INTO recipes(id,name,search_text,servings,portion_type,minutes,water_ml,steps,allergens,nutrition,provenance,seed_version,created_at) VALUES('home-012','醋熘白菜','醋熘白菜 大白菜 大豆油 糯米醋 岩盐',1,'dish',10,15,'["大白菜洗净，菜帮和菜叶分别切块。","锅中加入大豆油，先炒菜帮，再放入菜叶和15毫升水。","白菜炒熟后加入糯米醋和岩盐，翻炒均匀出锅。"]','["大豆"]','{"kcal":42.21,"protein":1.2,"fat":3.3,"carbs":3.07,"fiber":null,"sodiumMg":null,"sugar":null,"saturatedFat":null}','{"printedPage":30,"pdfPage":32,"excerpt":"醋熘白菜（白菜 100g）","changes":"保留原文主料用量；补充单菜调料克数、水量和制作步骤；食材按现有TFDA样品匹配。","matchNotes":"青菜选小白菜，牛瘦肉选修清前胸肉，鲈鱼选日本花鲈去皮可食肉，香干选五香豆干，盐选岩盐；使用对应样品估算。","sourceTitle":"成人肥胖食养指南（2024年版）","publisher":"国家卫生健康委办公厅","sourceUrl":"https://wjw.baoji.gov.cn/col2223/col2269/202403/P020241228641521653546.pdf","sourceSha256":"ce7e43937883f2d89bb3b505a410d023df510027e2015457d2800e98f5a330a2","nutritionSource":"TFDA","nutritionRelease":"snapshot-2026-10-20","calculation":"sum(raw_edible_or_as_sold_grams * TFDA_per100g / 100); no cooking retention or yield factor","stepsOrigin":"editorial","waterOrigin":"editorial"}','home-2024-v1','2026-10-20');
