INSERT INTO recipes(id,name,search_text,servings,portion_type,minutes,water_ml,steps,allergens,nutrition,provenance,seed_version,created_at) VALUES('home-013','清炒豆芽','清炒豆芽 绿豆芽 大豆油 岩盐',1,'dish',10,15,'["绿豆芽挑去腐烂部分，充分冲洗。","锅中加入大豆油，放入豆芽翻炒。","加入15毫升水和岩盐，持续加热至豆芽彻底熟透后盛出。"]','["大豆"]','{"kcal":47.53,"protein":2.3,"fat":3.2,"carbs":4.1,"fiber":null,"sodiumMg":null,"sugar":null,"saturatedFat":null}','{"printedPage":31,"pdfPage":33,"excerpt":"清炒豆芽（绿豆芽 100g）","changes":"保留原文主料用量；补充单菜调料克数、水量和制作步骤；食材按现有TFDA样品匹配。","matchNotes":"青菜选小白菜，牛瘦肉选修清前胸肉，鲈鱼选日本花鲈去皮可食肉，香干选五香豆干，盐选岩盐；使用对应样品估算。","sourceTitle":"成人肥胖食养指南（2024年版）","publisher":"国家卫生健康委办公厅","sourceUrl":"https://wjw.baoji.gov.cn/col2223/col2269/202403/P020241228641521653546.pdf","sourceSha256":"ce7e43937883f2d89bb3b505a410d023df510027e2015457d2800e98f5a330a2","nutritionSource":"TFDA","nutritionRelease":"snapshot-2026-10-20","calculation":"sum(raw_edible_or_as_sold_grams * TFDA_per100g / 100); no cooking retention or yield factor","stepsOrigin":"editorial","waterOrigin":"editorial"}','home-2024-v1','2026-10-20');
