INSERT INTO recipes(id,name,search_text,servings,portion_type,minutes,water_ml,steps,allergens,nutrition,provenance,seed_version,created_at) VALUES('home-014','山药香菇汤','山药香菇汤 鲜山药 西红柿 鲜香菇 岩盐',1,'dish',20,300,'["山药去皮切块，西红柿切块，鲜香菇切片。","锅中加入300毫升水，烧开后放入山药和鲜香菇。","煮约10分钟后加入西红柿，继续煮至全部食材软熟，加入岩盐拌匀。"]','[]','{"kcal":59.81,"protein":2.75,"fat":0.08,"carbs":13.38,"fiber":null,"sodiumMg":175.64,"sugar":null,"saturatedFat":null}','{"printedPage":24,"pdfPage":26,"excerpt":"山药香菇汤（鲜山药*50g，西红柿 50g，香菇【鲜】30g）","changes":"保留原文主料用量；补充单菜调料克数、水量和制作步骤；食材按现有TFDA样品匹配。","matchNotes":"青菜选小白菜，牛瘦肉选修清前胸肉，鲈鱼选日本花鲈去皮可食肉，香干选五香豆干，盐选岩盐；使用对应样品估算。","sourceTitle":"成人肥胖食养指南（2024年版）","publisher":"国家卫生健康委办公厅","sourceUrl":"https://wjw.baoji.gov.cn/col2223/col2269/202403/P020241228641521653546.pdf","sourceSha256":"ce7e43937883f2d89bb3b505a410d023df510027e2015457d2800e98f5a330a2","nutritionSource":"TFDA","nutritionRelease":"snapshot-2026-10-20","calculation":"sum(raw_edible_or_as_sold_grams * TFDA_per100g / 100); no cooking retention or yield factor","stepsOrigin":"editorial","waterOrigin":"editorial"}','home-2024-v1','2026-10-20');
