INSERT INTO recipes(id,name,search_text,servings,portion_type,minutes,water_ml,steps,allergens,nutrition,provenance,seed_version,created_at) VALUES('home-016','韭菜炒豆芽','韭菜炒豆芽 黄豆芽 韭菜 大豆油 岩盐',1,'dish',12,20,'["黄豆芽去除腐烂部分洗净，韭菜洗净切段。","锅中加入大豆油，放入黄豆芽和20毫升水，加热至豆芽彻底熟透。","加入韭菜和岩盐继续翻炒至熟，盛出食用。"]','["大豆"]','{"kcal":76.53,"protein":6.25,"fat":4.8,"carbs":6.95,"fiber":null,"sodiumMg":null,"sugar":null,"saturatedFat":0.83}','{"printedPage":24,"pdfPage":26,"excerpt":"韭菜炒豆芽（黄豆芽 100g，韭菜 50g）","changes":"保留原文主料用量；补充单菜调料克数、水量和制作步骤；食材按现有TFDA样品匹配。","matchNotes":"青菜选小白菜，牛瘦肉选修清前胸肉，鲈鱼选日本花鲈去皮可食肉，香干选五香豆干，盐选岩盐；使用对应样品估算。","sourceTitle":"成人肥胖食养指南（2024年版）","publisher":"国家卫生健康委办公厅","sourceUrl":"https://wjw.baoji.gov.cn/col2223/col2269/202403/P020241228641521653546.pdf","sourceSha256":"ce7e43937883f2d89bb3b505a410d023df510027e2015457d2800e98f5a330a2","nutritionSource":"TFDA","nutritionRelease":"snapshot-2026-10-20","calculation":"sum(raw_edible_or_as_sold_grams * TFDA_per100g / 100); no cooking retention or yield factor","stepsOrigin":"editorial","waterOrigin":"editorial"}','home-2024-v1','2026-10-20');
