INSERT INTO recipes(id,name,search_text,servings,portion_type,minutes,water_ml,steps,allergens,nutrition,provenance,seed_version,created_at) VALUES('home-017','芝麻菠菜','芝麻菠菜 菠菜 白芝麻 岩盐',1,'dish',10,0,'["白芝麻用干净平底锅小火炒熟，盛出放凉。","菠菜去根洗净，放入沸水中焯熟，捞出沥水切段。","菠菜加入炒熟的芝麻和岩盐拌匀，现做现吃。"]','["芝麻"]','{"kcal":64.61,"protein":3.33,"fat":5.64,"carbs":2.7,"fiber":null,"sodiumMg":128.8,"sugar":0.1,"saturatedFat":0.87}','{"printedPage":24,"pdfPage":26,"excerpt":"芝麻菠菜（菠菜 50g，白芝麻 10g）","changes":"保留原文主料用量；补充单菜调料克数、水量和制作步骤；食材按现有TFDA样品匹配。","matchNotes":"青菜选小白菜，牛瘦肉选修清前胸肉，鲈鱼选日本花鲈去皮可食肉，香干选五香豆干，盐选岩盐；使用对应样品估算。","sourceTitle":"成人肥胖食养指南（2024年版）","publisher":"国家卫生健康委办公厅","sourceUrl":"https://wjw.baoji.gov.cn/col2223/col2269/202403/P020241228641521653546.pdf","sourceSha256":"ce7e43937883f2d89bb3b505a410d023df510027e2015457d2800e98f5a330a2","nutritionSource":"TFDA","nutritionRelease":"snapshot-2026-10-20","calculation":"sum(raw_edible_or_as_sold_grams * TFDA_per100g / 100); no cooking retention or yield factor","stepsOrigin":"editorial","waterOrigin":"editorial"}','home-2024-v1','2026-10-20');
