INSERT INTO recipes(id,name,search_text,servings,portion_type,minutes,water_ml,steps,allergens,nutrition,provenance,seed_version,created_at) VALUES('home-018','清蒸虾仁','清蒸虾仁 冷冻大头虾仁 生姜 岩盐',1,'dish',15,0,'["冷冻虾仁在冷藏条件下解冻，清洗后去除虾线，生姜切丝。","虾仁放入蒸盘，加入姜丝和岩盐。","水沸后入锅蒸约8分钟，按虾仁大小延长时间，确认内部完全熟透后食用。"]','["甲壳类"]','{"kcal":28.95,"protein":6.18,"fat":0.15,"carbs":0.24,"fiber":null,"sodiumMg":638.98,"sugar":null,"saturatedFat":0.07}','{"printedPage":30,"pdfPage":32,"excerpt":"清蒸虾仁（冻虾仁 70g）","changes":"保留原文主料用量；补充单菜调料克数、水量和制作步骤；食材按现有TFDA样品匹配。","matchNotes":"青菜选小白菜，牛瘦肉选修清前胸肉，鲈鱼选日本花鲈去皮可食肉，香干选五香豆干，盐选岩盐；使用对应样品估算。","sourceTitle":"成人肥胖食养指南（2024年版）","publisher":"国家卫生健康委办公厅","sourceUrl":"https://wjw.baoji.gov.cn/col2223/col2269/202403/P020241228641521653546.pdf","sourceSha256":"ce7e43937883f2d89bb3b505a410d023df510027e2015457d2800e98f5a330a2","nutritionSource":"TFDA","nutritionRelease":"snapshot-2026-10-20","calculation":"sum(raw_edible_or_as_sold_grams * TFDA_per100g / 100); no cooking retention or yield factor","stepsOrigin":"editorial","waterOrigin":"editorial"}','home-2024-v1','2026-10-20');
