INSERT INTO recipes(id,name,search_text,servings,portion_type,minutes,water_ml,steps,allergens,nutrition,provenance,seed_version,created_at) VALUES('home-020','鸡蛋羹','鸡蛋羹 鸡蛋 岩盐',1,'dish',15,75,'["鸡蛋去壳称重后打散，加入75毫升温水和岩盐搅匀。","蛋液倒入耐热碗，盖上耐热盖，放入已经上汽的蒸锅。","中小火蒸约12分钟，确认中心完全凝固、熟透后食用。"]','["鸡蛋"]','{"kcal":67.51,"protein":6.35,"fat":4.45,"carbs":0.8,"fiber":null,"sodiumMg":172.4,"sugar":0.1,"saturatedFat":1.55}','{"printedPage":26,"pdfPage":28,"excerpt":"鸡蛋羹（鸡蛋 50g）","changes":"保留原文主料用量；补充单菜调料克数、水量和制作步骤；食材按现有TFDA样品匹配。","matchNotes":"青菜选小白菜，牛瘦肉选修清前胸肉，鲈鱼选日本花鲈去皮可食肉，香干选五香豆干，盐选岩盐；使用对应样品估算。","sourceTitle":"成人肥胖食养指南（2024年版）","publisher":"国家卫生健康委办公厅","sourceUrl":"https://wjw.baoji.gov.cn/col2223/col2269/202403/P020241228641521653546.pdf","sourceSha256":"ce7e43937883f2d89bb3b505a410d023df510027e2015457d2800e98f5a330a2","nutritionSource":"TFDA","nutritionRelease":"snapshot-2026-10-20","calculation":"sum(raw_edible_or_as_sold_grams * TFDA_per100g / 100); no cooking retention or yield factor","stepsOrigin":"editorial","waterOrigin":"editorial"}','home-2024-v1','2026-10-20');
